def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list) or len(items) != 1:
        return False
    if data.get("hasMore") is not False:
        return False
    if data.get("nextCursor") is not None:
        return False
    item = items[0]
    if not isinstance(item, dict) or item.get("toUserId") != globalParam.get("b_id"):
        return False
    seen = [globalParam.get("r1_from"), globalParam.get("r2_from"), item.get("fromUserId")]
    ids = [globalParam.get("r1_id"), globalParam.get("r2_id"), item.get("id")]
    expected = [globalParam.get("a_id"), globalParam.get("c_id"), globalParam.get("d_id")]
    if not all(seen) or not all(ids) or not all(expected):
        return False
    return len(set(seen)) == 3 and set(seen) == set(expected) and len(set(ids)) == 3 and bool(responseBody.get("requestId"))

